                        // per element (a, b) and axis k: M1[k] += s_i s_k SUM_t E^a_t U[t + 1_k] over
                        // the live t, rolled over the P tables (the Hermite shift); (-1)^|tau| =
                        // (-1)^4 on every live tau
                        for (int32_t a_u = 0; a_u < 2; a_u += 1) {
                            for (int32_t a_w = 0; a_w < (a_u + 1); a_w += 1) {
                                int32_t ax = (1 - a_u);
                                int32_t ay = (a_u - a_w);
                                int32_t az = a_w;
                                int32_t ra = (((a_u * (a_u + 1)) / 2) + a_w);
                                double v0 = 0.0;
                                for (int32_t e0_tx = (ax - (2 * (ax / 2))); e0_tx < (ax + 1); e0_tx += 2) {
