                                M1[((0 * n_aux + (op + ra)) * n_aux + (oq + rb))] = (M1[((0 * n_aux + (op + ra)) * n_aux + (oq + rb))] + (w * v0));
                                double v1 = 0.0;
                                for (int32_t e1_tx = (ax - (2 * (ax / 2))); e1_tx < (ax + 1); e1_tx += 2) {
